text:
{
 "reason": {
  "es": "内閣《ないかく》は、独立行政法人《どくりつぎょうせいほうじん》男女共同参画《だんじょきょうどうさんかく》機構《きこう》法《ほう》という新《あたら》しい法律《ほうりつ》が始《はじ》まるのにあわせて、男女共同参画社会基本法《だんじょきょうどうさんかくしゃかいきほんほう》に、独立行政法人《どくりつぎょうせいほうじん》男女共同参画《だんじょきょうどうさんかく》機構《きこう》の役《やく》わりを書《か》くため、としている。男女共同参画《だんじょきょうどうさんかく》とは、男《おとこ》の人《ひと》も女《おんな》の人《ひと》も、同《おな》じように社会《しゃかい》のいろいろなことに参加《さんか》できるようにすることだ。ほかの法律《ほうりつ》のきまりも整《ととの》える必要《ひつよう》があるため、としている。",
  "hs": "内閣は、独立行政法人男女共同参画機構法の施行《しこう》（実際に使われ始めること）にともない、男女共同参画社会基本法に、男女共同参画社会づくりの施策《しさく》を進める機関としての独立行政法人男女共同参画機構の役割を定めるほか、関係する法律の規定を整える必要があるため、としている。",
  "std": "内閣は、独立行政法人男女共同参画機構法の施行に伴い、男女共同参画社会基本法において、男女共同参画社会の形成の促進に関する施策を推進するための機関としての独立行政法人男女共同参画機構の役割を定めるほか、関係法律の規定の整備などを行う必要があるためとしている。",
  "univ": "内閣は、独立行政法人男女共同参画機構法の施行に伴い、男女共同参画社会基本法において男女共同参画社会の形成の促進に関する施策を推進するための機関としての独立行政法人男女共同参画機構の役割を定めるほか、関係法律の規定の整備等を行う必要があるためとしている。"
 },
 "who": {
  "es": "国《くに》と、都道府県《とどうふけん》や市町村《しちょうそん》（地方公共団体《ちほうこうきょうだんたい》）。関係《かんけい》する人《ひと》たちが協力《きょうりょく》しあうための取《と》り組《く》みや、男女共同参画《だんじょきょうどうさんかく》に取《と》り組《く》む人《ひと》を集《あつ》めて育《そだ》てる取《と》り組《く》みをするように、努《つと》めることになる。地方公共団体《ちほうこうきょうだんたい》は、男女共同参画《だんじょきょうどうさんかく》センター（地域《ちいき》の取《と》り組《く》みの中心《ちゅうしん》になる場所《ばしょ》）のはたらきをもつしくみを作《つく》るように努《つと》める。男女共同参画《だんじょきょうどうさんかく》センターのはたらきをもつところ（独立行政法人《どくりつぎょうせいほうじん》男女共同参画《だんじょきょうどうさんかく》機構《きこう》と、しっかり協力《きょうりょく》するように努《つと》める）。独立行政法人《どくりつぎょうせいほうじん》男女共同参画《だんじょきょうどうさんかく》機構《きこう》と、男女共同参画《だんじょきょうどうさんかく》の活動《かつどう》をする民間《みんかん》の団体《だんたい》など。",
  "hs": "国と地方公共団体（関係者どうしの連携《れんけい》・協働を進める施策《しさく》や、人材の確保・養成の施策《しさく》に努める）。地方公共団体（単独または共同で、男女共同参画センターの機能を担う体制の確保に努める）。男女共同参画センターの機能を担う者（独立行政法人男女共同参画機構との密接な連携《れんけい》に努める）。独立行政法人男女共同参画機構と、男女共同参画に関する活動を行う民間の団体等。",
  "std": "国と地方公共団体（関係者相互の連携・協働を促進する施策や、人材の確保・養成・資質向上の施策を講じるよう努める）。地方公共団体（単独または共同で、男女共同参画センターとしての機能を担う体制の確保に努める）。男女共同参画センターとしての機能を担う者（機構と密接に連携するよう努める）。独立行政法人男女共同参画機構と、男女共同参画社会の形成促進の活動を行う民間の団体等。",
  "univ": "国及び地方公共団体（関係者相互間の連携と協働を促進するために必要な施策、男女共同参画社会の形成の促進に取り組む人材の確保、養成及び資質の向上に必要な施策を講ずる努力義務）。地方公共団体（単独で又は共同して、男女共同参画センターとしての機能を担う体制を確保する努力義務）。男女共同参画センターとしての機能を担う者（機構と密接に連携する努力義務）。独立行政法人男女共同参画機構及び男女共同参画社会の形成の促進に関する施策に関する活動を行う民間の団体等。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》では、内閣委員会《ないかくいいんかい》で、独立行政法人《どくりつぎょうせいほうじん》男女共同参画《だんじょきょうどうさんかく》機構《きこう》法《ほう》案《あん》といっしょに話《はな》し合《あ》った。三原《みはら》大臣《だいじん》が説明《せつめい》し、質問《しつもん》と討論《とうろん》のあと、2つとも賛成《さんせい》が多《おお》く、そのまま通《とお》った。委員会《いいんかい》からの注文《ちゅうもん》（附帯決議《ふたいけつぎ》）もついた。参議院《さんぎいん》でも、内閣委員会《ないかくいいんかい》で2つをいっしょに話《はな》し合《あ》った。男女共同参画社会《だんじょきょうどうさんかくしゃかい》に向《む》けた取《と》り組《く》みのようす、新《あたら》しくできる機構《きこう》のはたらきを強《つよ》くする方法《ほうほう》、国立《こくりつ》女性《じょせい》教育《きょういく》会館《かいかん》の研修《けんしゅう》の建物《たてもの》などをとりこわすことへの対応《たいおう》などについて、質問《しつもん》があった。日本維新《にっぽんいしん》の会《かい》は、機構《きこう》法《ほう》案《あん》に「3年《ねん》いないに見直《みなお》しを考《かんが》える」というきまりを加《くわ》える直《なお》す案《あん》（修正案《しゅうせいあん》）を出《だ》した。討論《とうろん》では、日本維新《にっぽんいしん》の会《かい》、日本共産党《にほんきょうさんとう》、れいわ新選組《しんせんぐみ》が、もとの2つの法律案《ほうりつあん》に反対《はんたい》した。修正案《しゅうせいあん》は賛成《さんせい》が少《すく》なく、みとめられなかった。2つの法律案《ほうりつあん》は、賛成《さんせい》が多《おお》く、そのまま通《とお》った。附帯決議《ふたいけつぎ》もついた。",
  "hs": "衆議院では内閣委員会で、独立行政法人男女共同参画機構法案とあわせて審査《しんさ》した。三原国務大臣が趣旨《しゅし》を説明し、質疑と討論のあと、両案とも賛成多数で原案のとおり可決され、附帯決議《ふたいけつぎ》（委員会がつける注文）がついた。参議院でも内閣委員会で両案を一括《いっかつ》して審査《しんさ》し、男女共同参画社会の実現に向けた取り組みの状況《じょうきょう》、新しい機構の機能強化の方策、国立女性教育会館の研修施設《けんしゅうしせつ》などの撤去《てっきょ》をめぐる対応などについて質疑があった。日本維新《にっぽんいしん》の会は、機構法案の附則《ふそく》に施行後《しこうご》3年以内の検討｜条項《じょうこう》を加える修正案を出した。討論では日本維新《にっぽんいしん》の会、日本共産党、れいわ新選組が両案の原案に反対した。修正案は賛成少数で否決され、両案は多数で原案どおり可決された。附帯決議《ふたいけつぎ》がついた。",
  "std": "衆議院内閣委員会では、独立行政法人男女共同参画機構法案と一括して審査し、三原国務大臣の趣旨説明、質疑、討論を経て、両案とも賛成多数で原案のとおり可決した。附帯決議が付された。参議院内閣委員会では、両案を一括して議題とし、男女共同参画社会の実現に向けた取組状況、新設される機構の機能強化のための方策、国立女性教育会館の研修施設等の撤去をめぐる対応などについて質疑が行われた。日本維新の会が、機構法案の附則に施行後3年以内の検討条項を追加する修正案を提出した。討論では日本維新の会、日本共産党、れいわ新選組が両案の原案に反対の意見を述べた。修正案は賛成少数で否決され、両案は多数で原案どおり可決すべきものと決定した。附帯決議が付された。",
  "univ": "衆議院内閣委員会では、両法律案が6月5日に付託され、翌6日三原国務大臣から趣旨の説明を聴取し、11日に質疑を行い、質疑終局後、討論、採決の結果、両案はいずれも賛成多数をもって原案のとおり可決すべきものと決した。両法律案に対し附帯決議が付された。参議院内閣委員会では、両法律案を一括して議題とし、男女共同参画社会の実現に向けた取組状況、新設される機構の機能強化のための方策、国立女性教育会館の研修施設等の撤去をめぐる対応等について質疑が行われた。質疑終局後、日本維新の会を代表して片山委員より、機構法案の附則に施行後3年以内の検討条項を追加する旨の修正案が提出された。討論では、日本維新の会の片山委員より両法律案の原案に反対、機構法案の修正案に賛成、日本共産党の井上委員及びれいわ新選組の大島委員より両法律案の原案及び機構法案の修正案に反対の旨の意見がそれぞれ述べられた。採決の結果、修正案は賛成少数をもって否決され、両法律案はいずれも多数をもって原案どおり可決すべきものと決定された。両法律案に対し附帯決議が行われた。"
 },
 "views": [
  {
   "side": "反対",
   "group": "日本維新の会",
   "where": "衆議院 本会議、衆議院 内閣委員会、参議院 内閣委員会",
   "text": {
    "es": "日本維新《にっぽんいしん》の会《かい》は、男女共同参画社会《だんじょきょうどうさんかくしゃかい》を作《つく》ることはとても大切《たいせつ》だとした。そのうえで、反対《はんたい》の理由《りゆう》として、次《つぎ》のことを話《はな》した。国立《こくりつ》女性《じょせい》教育《きょういく》会館《かいかん》（ＮＷＥＣ）のこれまでの成果《せいか》や反省《はんせい》を、政府《せいふ》が十分《じゅうぶん》に調《しら》べていないこと。新《あたら》しい機構《きこう》の目標《もくひょう》も、はっきりしていないこと。新《あたら》しい機構《きこう》の仕事《しごと》は、独立行政法人《どくりつぎょうせいほうじん》でなければできないものではないこと。とまるための建物《たてもの》がなくなるのに、交通《こうつう》が不便《ふべん》な埼玉県《さいたまけん》嵐山町《らんざんまち》におく必要《ひつよう》はないこと。",
    "hs": "日本維新《にっぽんいしん》の会は、男女共同参画社会の形成は非常に重要だとしたうえで、反対した。理由として、国立女性教育会館（ＮＷＥＣ）の成果や反省点を政府が十分に評価しておらず、新法人の明確な目標もないこと、新機構の業務は独立行政法人でなければ行えないものではないこと、宿泊《しゅくはく》研修の機能がなくなるのに交通の便が悪い埼玉県｜嵐山町《らんざんまち》に置く必要はないことを述べた。",
    "std": "日本維新の会は、男女共同参画社会の形成は重要だとした上で、国立女性教育会館（ＮＷＥＣ）の成果や反省点について政府の評価が不十分で新法人の明確な目標設定もないこと、新機構の業務は独立行政法人でなければ行えないものではないこと、宿泊研修機能がなくなるのに交通の便の悪い埼玉県嵐山町に置く必要はないことを理由に反対した。",
    "univ": "日本維新の会は、男女共同参画社会の形成は非常に重要であるとした上で、独立行政法人国立女性教育会館（ＮＷＥＣ）の成果や反省点について政府は十分に評価を行えておらず新法人の明確な目標設定もなされていないこと、ＮＷＥＣを廃止し新機構を設立する合理的な根拠は乏しく新機構の業務は独立行政法人でなければ行えないものではないこと、宿泊研修機能を持たなくなるのであれば交通の便の悪い埼玉県嵐山町に存置する必要はないことを理由に反対した。"
   }
  },
  {
   "side": "反対",
   "group": "れいわ新選組",
   "where": "衆議院 本会議、衆議院 内閣委員会、参議院 内閣委員会",
   "text": {
    "es": "れいわ新選組《しんせんぐみ》は、男女共同参画《だんじょきょうどうさんかく》センターを法律《ほうりつ》の中《なか》にきちんと書《か》くことに反対《はんたい》はないとした。でも、顔《かお》を合《あ》わせて話《はな》し合《あ》う場《ば》になる、とまって研修《けんしゅう》する建物《たてもの》をとりこわすのは、まちがった進《すす》め方《かた》だとした。また、ＮＷＥＣへの国《くに》のお金《かね》がへらされ続《つづ》けてきたように、お金《かね》の助《たす》けが足《た》りず、機構《きこう》やセンターのはたらきがかえって小《ちい》さくなるおそれがあるとして、反対《はんたい》した。",
    "hs": "れいわ新選組は、男女共同参画センターを法的に位置づけることに異論はないとしつつ、対面で意見を交わす場となる宿泊《しゅくはく》研修施設《けんしゅうしせつ》を撤去《てっきょ》するのは本末転倒《ほんまつてんとう》（大事なことと、そうでないことが逆になること）だとした。また、ＮＷＥＣへの運営費交付金が削《けず》られ続けてきたなど財政支援《ざいせいしえん》が不十分で、機構やセンターの機能がかえって縮小するおそれがあるとして反対した。",
    "std": "れいわ新選組は、男女共同参画センターを法的に位置づけることに異論はないとしつつ、対面で議論を交わす場となる宿泊研修施設の撤去は本末転倒だとした。また、ＮＷＥＣへの運営費交付金が削減され続けてきたなど財政支援が不十分で、機構や男女共同参画センターが全体として機能縮小するおそれがあるとして反対した。",
    "univ": "れいわ新選組は、各地の男女共同参画センターを法的に位置づけ機構との連携やネットワークの強化を目指すことには一般論として異議はないとしつつ、様々な関係者が対面で議論を交わす場となる宿泊研修施設の撤去は本末転倒であるとした。また、ＮＷＥＣへの運営費交付金が2001年以降削減され続けてきたなど財政支援が不十分であり、十分な財政支援がなければ機構や男女共同参画センターが全体として機能縮小、閉鎖されるのではないかという懸念があるとして反対した。"
   }
  },
  {
   "side": "反対",
   "group": "日本共産党",
   "where": "衆議院 本会議、衆議院 内閣委員会、参議院 内閣委員会",
   "text": {
    "es": "日本共産党《にほんきょうさんとう》は、地方《ちほう》の男女共同参画《だんじょきょうどうさんかく》センターを、はじめて法律《ほうりつ》に書《か》くことなどは前《まえ》に進《すす》んだ点《てん》だとした。でも、研修《けんしゅう》の建物《たてもの》やとまる建物《たてもの》をなくすことは、顔《かお》を合《あ》わせた研修《けんしゅう》や市民《しみん》の活動《かつどう》の場《ば》をうばい、機構《きこう》のはたらきを後《あと》もどりさせるとした。国《くに》のお金《かね》を約《やく》3わりへらしてきた政府《せいふ》の考《かんが》え方《かた》を改《あらた》め、十分《じゅうぶん》にお金《かね》を出《だ》すべきだと話《はな》し、反対《はんたい》した。",
